            .device = render_device,
            .config = renderer_config,
            .font_grid = font_grid,
            .size = size,
            .surface_mailbox = .{ .surface = self, .app = app_mailbox },
            .rt_surface = rt_surface,
            .thread = &self.renderer_thread,
